llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "2-Methoxyestradiol, a close estradiol analogue with a phenolic A-ring, has clinical oral bioavailability of only 1–2%, strongly supporting low F for the estradiol-based query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Progesterone, a steroid with the same fused tetracyclic scaffold, has ingested bioavailability of less than 10%, supporting low oral F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine, a phenolic fused-ring opioid, has mean oral bioavailability of 18% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Butorphanol, a lipophilic opioid with a phenolic/fused-ring core, has oral bioavailability of about 5% due to first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Danazol, a lipophilic steroid, has absolute oral bioavailability of 11 ± 5.2% in the fasted state, showing that lipophilic steroids can have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Estramustine phosphate, an estradiol ester prodrug, has very low oral bioavailability of the parent drug, consistent with low F for the query's 17β-ester.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Some estramustine phosphate patient data report a mean oral bioavailability of 43.7%, indicating formulation or active-metabolite variability, but this is outweighed by more direct low-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is estradiol cypionate, a lipophilic 17β-ester of estradiol. The closest high-transfer analogues—2-methoxyestradiol, progesterone, and phenolic opioids—show low oral bioavailability (1–18%), and an estradiol ester prodrug has very low parent-drug oral bioavailability. Although some estramustine phosphate patient data and fed-state formulations show higher F, the preponderance of transferable evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability data for estradiol cypionate itself.",
    "Ambiguity between parent-drug versus active-metabolite bioavailability for ester prodrugs such as estramustine phosphate.",
    "Formulation and fed-state effects could alter F, as seen with danazol, but are not defined for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

